package org.sleepwell.app;
import android.content.*;import android.content.pm.ActivityInfo;import android.net.Uri;import android.os.Bundle;import android.provider.AlarmClock;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public final class AlarmRequestStorageTest {
    @Test public void standardFieldsCreateIndependentDraftAndIgnoreNestedAuthority()throws Exception{Intent input=new Intent(AlarmClock.ACTION_SET_ALARM).putExtra(AlarmClock.EXTRA_HOUR,6).putExtra(AlarmClock.EXTRA_MINUTES,25).putExtra(AlarmClock.EXTRA_MESSAGE,"Morning visit").putExtra(AlarmClock.EXTRA_SKIP_UI,true).putExtra("alarm","malicious").putExtra("next",new Intent().setAction("STOP"));input.putIntegerArrayListExtra(AlarmClock.EXTRA_DAYS,new ArrayList<>(List.of(2,4)));Alarm template=new Alarm(8);template.volume=42;template.enabled=false;String before=template.json().toString();Alarm draft=AlarmRequestInput.read(input).draft(template);assertEquals(8,draft.id);assertEquals(6,draft.hour);assertEquals(25,draft.minute);assertEquals(Set.of(1,3),draft.days);assertEquals("Morning visit",draft.label);assertEquals(42,draft.volume);assertTrue(draft.enabled);assertNull(draft.skip);assertNull(draft.date);assertEquals(before,template.json().toString());}
    @Test public void malformedFieldsUrisUnsupportedSoundsAndActionsNeverProduceDrafts(){for(Intent bad:new Intent[]{new Intent("other"),new Intent(AlarmClock.ACTION_SET_ALARM).setData(Uri.parse("content://fixture/item")),new Intent(AlarmClock.ACTION_SET_ALARM).putExtra(AlarmClock.EXTRA_HOUR,"6"),new Intent(AlarmClock.ACTION_SET_ALARM).putExtra(AlarmClock.EXTRA_SKIP_UI,1),new Intent(AlarmClock.ACTION_SET_ALARM).putExtra(AlarmClock.EXTRA_RINGTONE,"silent")})assertThrows(IllegalArgumentException.class,()->AlarmRequestInput.read(bad));Intent wrongDays=new Intent(AlarmClock.ACTION_SET_ALARM).putExtra(AlarmClock.EXTRA_DAYS,"Monday");assertThrows(IllegalArgumentException.class,()->AlarmRequestInput.read(wrongDays));}
    @Test public void onlyTheStandardPermissionProtectedActivityIsPublic()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();ActivityInfo entry=c.getPackageManager().getActivityInfo(new ComponentName(c,AlarmRequestActivity.class),0);assertTrue(entry.exported);assertEquals("com.android.alarm.permission.SET_ALARM",entry.permission);assertFalse(c.getPackageManager().getActivityInfo(new ComponentName(c,AlarmEditorActivity.class),0).exported);assertFalse(AlarmService.active);assertFalse(TrackingService.running);}
}
